<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();fleet_cert_require_same_origin_post();$db=fleet_db();$actor=(int)$user['id'];
$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in))json_response(['ok'=>false,'message'=>'Invalid maintenance request.'],400);
try{$action=(string)($in['action']??'');if($action==='save_checks')fleet_cert_require_permission($user,'maintenance.inspect');elseif($action==='resolve_defect')fleet_cert_require_permission($user,'maintenance.resolve_defects');$db->beginTransaction();
 if($action==='save_checks'){
  $assetId=(int)($in['asset_id']??0);$driverId=(int)($in['driver_id']??0);$tripId=(int)($in['trip_id']??0);$odometer=trim((string)($in['odometer']??''));$odometer=$odometer===''?null:filter_var($odometer,FILTER_VALIDATE_INT);if($odometer!==null&&$odometer===false)throw new InvalidArgumentException('Enter a valid odometer reading.');
  $q=$db->prepare('SELECT a.id,t.type_code FROM assets a JOIN asset_types t ON t.id=a.asset_type_id WHERE a.id=? AND a.is_active=1 FOR UPDATE');$q->execute([$assetId]);$asset=$q->fetch();if(!$asset)throw new InvalidArgumentException('Choose an active asset.');
  $keys=['brakes','tyres','wheel_fixings','lights_indicators','steering','mirrors_windows','wipers_washers','horn','fluids_leaks','body_condition','safety_equipment','vehicle_documents','load_security','coupling'];$inputChecks=$in['checklist']??[];if(!is_array($inputChecks))throw new InvalidArgumentException('Complete the vehicle checklist.');$checks=[];$defects=[];foreach($keys as $key){if($key==='coupling'&&$asset['type_code']==='TRUCK_HEAD')continue;$value=(string)($inputChecks[$key]??'');if(!in_array($value,['OK','DEFECT','NA'],true))throw new InvalidArgumentException('Complete every vehicle inspection item.');$checks[$key]=$value;if($value==='DEFECT')$defects[]=$key;}
  $criticalKeys=['brakes','tyres','wheel_fixings','lights_indicators','steering','fluids_leaks','safety_equipment','load_security','coupling'];$critical=count(array_intersect($criticalKeys,$defects));$result=$critical?'OUT_OF_SERVICE':($defects?'DEFECT':'PASS');$notes=trim((string)($in['inspection_notes']??''));if(mb_strlen($notes)>1000)throw new InvalidArgumentException('Inspection notes are too long.');
  if($tripId){$q=$db->prepare('SELECT id FROM fleet_trips WHERE id=? AND status IN (\'PENDING\',\'APPROVED\')');$q->execute([$tripId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The selected trip is no longer active.');}
  $workOrderId=(int)($in['work_order_id']??0);if($workOrderId){$q=$db->prepare("SELECT id FROM maintenance_work_orders WHERE id=? AND asset_id=? AND status='REPAIR_COMPLETE' FOR UPDATE");$q->execute([$workOrderId,$assetId]);if(!$q->fetchColumn())throw new InvalidArgumentException('Select a repair-complete work order for this same asset.');}
  $q=$db->prepare('INSERT INTO vehicle_inspections(trip_id,work_order_id,asset_id,checked_by,odometer,result,checklist_json,critical_defects,notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$tripId?:null,$workOrderId?:null,$assetId,$actor,$odometer,$result,json_encode($checks,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$critical,$notes?:null]);$inspectionId=(int)$db->lastInsertId();
  if($defects){$summary='Defects: '.implode(', ',array_map(static fn($k)=>str_replace('_',' ',$k),$defects));$severity=$critical?'CRITICAL':'MEDIUM';$q=$db->prepare('INSERT INTO maintenance_logs(asset_id,inspection_id,reported_by,defect_summary,severity) VALUES(?,?,?,?,?)');$q->execute([$assetId,$inspectionId,$actor,$summary,$severity]);}
  $fitnessResult='NOT_CHECKED';$fitnessId=null;if($driverId){$q=$db->prepare('SELECT id FROM drivers WHERE id=? AND is_active=1');$q->execute([$driverId]);if(!$q->fetchColumn())throw new InvalidArgumentException('Choose an active driver.');$q=$db->prepare('SELECT da.id FROM asset_driver_assignments da WHERE da.driver_id=? AND da.assigned_to IS NULL AND (da.asset_id=? OR EXISTS(SELECT 1 FROM asset_attachments aa WHERE aa.head_asset_id=da.asset_id AND aa.trailer_asset_id=? AND aa.attached_to IS NULL)) LIMIT 1');$q->execute([$driverId,$assetId,$assetId]);if(!$q->fetchColumn())throw new InvalidArgumentException('The selected driver must be currently assigned to this Horse or its linked Horse.');$licenceChecked=!empty($in['licence_checked'])?1:0;$licenceExpiry=trim((string)($in['licence_expiry']??''));$licenceExpiry=$licenceExpiry?:null;if(!$licenceExpiry||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$licenceExpiry))throw new InvalidArgumentException('Enter the driver licence expiry date to verify it.');$rested=!empty($in['rested'])?1:0;$fit=!empty($in['fit_to_drive'])?1:0;$fitnessResult=($licenceChecked&&$rested&&$fit&&$licenceExpiry>=date('Y-m-d'))?'PASS':'FAIL';$fitnessNotes=trim((string)($in['fitness_notes']??''));if(mb_strlen($fitnessNotes)>1000)throw new InvalidArgumentException('Driver check notes are too long.');$q=$db->prepare('INSERT INTO driver_fitness_checks(trip_id,driver_id,checked_by,licence_checked,licence_expiry,rested,fit_to_drive,result,notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$tripId?:null,$driverId,$actor,$licenceChecked,$licenceExpiry,$rested,$fit,$fitnessResult,$fitnessNotes?:null]);$fitnessId=(int)$db->lastInsertId();}
  fleet_cert_log($db,$actor,'CREATE','VEHICLE_INSPECTION',$inspectionId,'Recorded '.$result.' vehicle inspection for asset '.$assetId.($driverId?' and fit-to-drive '.$fitnessResult.' for driver '.$driverId:''));$db->commit();$fitnessRef=$fitnessId?'FIT-'.str_pad((string)$fitnessId,6,'0',STR_PAD_LEFT):null;json_response(['ok'=>true,'message'=>'Inspection saved: '.$result.($driverId?' · driver fitness: '.$fitnessResult.' · reference: '.$fitnessRef:''),'inspection_id'=>$inspectionId,'fitness_check_id'=>$fitnessId,'fitness_check_reference'=>$fitnessRef,'result'=>$result,'critical_defects'=>$critical]);
 }
 if($action==='resolve_defect'){$id=(int)($in['id']??0);$correction=trim((string)($in['corrective_action']??''));if(!$id||$correction==='')throw new InvalidArgumentException('Enter the repair or corrective action taken.');if(mb_strlen($correction)>1000)throw new InvalidArgumentException('The corrective action is too long.');$q=$db->prepare('SELECT id FROM maintenance_logs WHERE id=? AND resolved_at IS NULL FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn())throw new InvalidArgumentException('This defect is already resolved or does not exist.');$q=$db->prepare('UPDATE maintenance_logs SET corrective_action=?,resolved_by=?,resolved_at=NOW() WHERE id=?');$q->execute([$correction,$actor,$id]);fleet_cert_log($db,$actor,'RESOLVE','MAINTENANCE_LOG',$id,'Resolved maintenance defect '.$id.': '.$correction);$db->commit();json_response(['ok'=>true,'message'=>'Repair recorded. Submit a fresh inspection to clear the vehicle.']);}

 throw new InvalidArgumentException('Choose a valid maintenance action.');
}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Maintenance update: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The maintenance update could not be saved. No changes were applied.'],500);}
